package com.bank.named.model;

import jakarta.persistence.*;
import java.math.BigDecimal;

@Entity
@Table(name = "accounts")
// JPQL named query — PARSED & VALIDATED at startup (fails boot on typo)
@NamedQuery(
    name = "Account.findActiveByType",
    query = "select a from Account a where a.status = 'ACTIVE' and a.type = :type")
// Native SQL named query + result mapping into a DTO
@NamedNativeQuery(
    name = "Account.sumActiveBalanceByType",
    query = "SELECT type AS type, SUM(balance) AS totalBalance " +
            "FROM accounts WHERE status = 'ACTIVE' GROUP BY type",
    resultSetMapping = "BalanceSummaryMapping")
@SqlResultSetMapping(
    name = "BalanceSummaryMapping",
    classes = @ConstructorResult(
        targetClass = com.bank.named.dto.BalanceSummary.class,
        columns = {
            @ColumnResult(name = "type", type = String.class),
            @ColumnResult(name = "totalBalance", type = BigDecimal.class)
        }))
public class Account {
    @Id private String id;
    private String holderName;
    private String type;
    private BigDecimal balance;
    private String status;

    protected Account() { }
    public String getId() { return id; }
    public BigDecimal getBalance() { return balance; }
}
