package com.bank.named.repository;

import com.bank.named.model.Account;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import java.util.List;

public interface AccountRepository extends JpaRepository<Account, String> {

    // Spring Data finds the @NamedQuery "Account.findActiveByType" by convention
    List<Account> findActiveByType(@Param("type") String type);

    // Inline @Query for contrast — local to this method, also JPQL-validated at startup
    @Query("select a from Account a where a.balance > :min")
    List<Account> findRicherThan(@Param("min") java.math.BigDecimal min);
}
