package com.bank.named.service;

import com.bank.named.dto.BalanceSummary;
import com.bank.named.model.Account;
import com.bank.named.repository.AccountRepository;
import jakarta.persistence.EntityManager;
import jakarta.persistence.PersistenceContext;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.math.BigDecimal;
import java.util.List;

@Service
@RequiredArgsConstructor
@Slf4j
public class AccountQueryService {

    private final AccountRepository accountRepo;

    @PersistenceContext
    private EntityManager em;

    @Transactional(readOnly = true)
    public List<Account> activeSavings() {
        // uses the startup-validated @NamedQuery via the repository
        return accountRepo.findActiveByType("SAVINGS");
    }

    @Transactional(readOnly = true)
    @SuppressWarnings("unchecked")
    public List<BalanceSummary> balanceByType() {
        // invoke the named NATIVE query by name, mapped into the DTO
        List<BalanceSummary> rows =
            em.createNamedQuery("Account.sumActiveBalanceByType").getResultList();
        log.info("Native named query returned {} summary rows", rows.size());
        return rows;
    }
}
